join (values ('Traditional Treatments', 'Relaxing Massage', 'Warm herbal oil is poured onto your body, followed by a soothing Ayurvedic-inspired massage to calm the nervous system and relieve deep stress, leaving you balanced, relaxed, and fully restored.', 375000, 'IDR', 0), ('Traditional Treatments', 'Balinese Massage', 'Experience Balinese massage techniques—pressure points, palm pressure, sliding, and kneading for deep relaxation. Release muscle tension, ease pain, and enjoy profound therapeutic benefits.', 325000, 'IDR', 1), ('Traditional Treatments', 'Exfoliation and Bath', 'Choose your scrub—lulur, milk, coffee, or green tea—to revitalize your skin. Finish your treatment by relaxing in a beautiful floral bath for a perfect, refreshing feeling.', 350000, 'IDR', 2), ('Traditional Treatments', 'Mandi Lulur – Floral Bath', 'Experience a 17th-century Javanese royal treatment with a 75-minute relaxing massage, a traditional full-body spice scrub, and a fragrant floral bath overlooking the jungle.', 550000, 'IDR', 3), ('Traditional Treatments', 'Mandi Susu – Milk Bath', 'Experience a timeless beauty ritual inspired by Cleopatra, with a 75-minute relaxing massage, a gentle milk scrub, and a fragrant floral bath for soft, smooth, and glowing skin.', 550000, 'IDR', 4), ('Traditional Treatments', 'Mandi Kopi – Coffee Bath', 'Enjoy an invigorating treatment with a 75-minute relaxing massage, a coffee scrub to smooth and tone the skin, and a fragrant floral bath for a refreshed, renewed feeling.', 550000, 'IDR', 5), ('Traditional Treatments', 'Mandi Teh Hijau – Green Tea Bath', 'A detoxifying treatment featuring a 75-minute relaxing massage, followed by a green tea scrub to rejuvenate the skin. Finish with a beautiful floral bath for a radiant and refreshed glow.', 550000, 'IDR', 6), ('Traditional Treatments', 'Mandi Rempah – Spice Bath', 'Experience a 75-minute relaxing massage, a warming spice scrub to improve circulation, and an aromatic herbal bath to soothe, restore, and renew your body.', 550000, 'IDR', 7), ('Traditional Treatments', 'Coconut Body Treatment', 'A deeply hydrating ritual combining a relaxing massage, a gentle coconut body scrub, and a fresh flower bath—ideal for dry and compromised skin.', 550000, 'IDR', 8), ('Traditional Treatments', 'Floral Bath Only', 'Immerse yourself in a fresh flower petal bath designed to rejuvenate the senses. Enjoy a quiet moment of relaxation for the body and mind.', 250000, 'IDR', 9), ('Traditional Treatments', 'Foot Spa', 'Treat your feet to a relaxing foot spa with a salt and lime soak, nail care, and a 25-minute massage for your feet and lower legs, leaving them refreshed, smooth, and well-groomed.', 275000, 'IDR', 10), ('Traditional Treatments', 'Gel Mask Facial', 'Our therapists gently cleanse and exfoliate your skin before applying a Bio-Aloe Vera mask that hydrates the skin and locks in moisture. The perfect soothing facial for normal to dry skin types, and those who have caught too much Bali sun.', 350000, 'IDR', 11), ('Traditional Treatments', 'Thermal Clay Facial', 'Specially crafted for oily or sensitive skin types, our Balinese clay facial is nature’s facelift! After the therapists gently cleanse and exfoliate your skin, a thermal clay mask is applied to your face and neck to purify and hydrate your skin, restoring its radiance.', 350000, 'IDR', 12), ('Traditional Treatments', 'Hair Cream Bath', 'Rejuvenate dull hair with an avocado cream scalp massage to stimulate circulation and promote growth, followed by a steam bath to lock in moisture for healthy, shiny hair.', 300000, 'IDR', 13), ('Traditional Treatments', 'Hibiscus Hair Shampoo', 'This centuries-old Indonesian ritual cleanses and nourishes your scalp with hibiscus extract to stimulate growth, prevent graying, and reveal lustrous hair.', 150000, 'IDR', 14), ('Traditional Treatments', 'Ayurvedic Facial', 'Our therapists gently cleanse and exfoliate your skin using a classic blend of antioxidant-rich herbs. A soothing Marma point massage calms you, before steam deeply purifies your pores. This facial revives skin texture, restores elasticity to prevent aging and gives you a radiant glow.', 400000, 'IDR', 15)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

