with target as (
  select slug from venues where slug = 'ely-s-kitchen-ubud' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Beverage List', 1, 'draft', 'partial', 'https://e-catalogue.elyskitchenubud.com/wp-content/uploads/2024/08/202501_ekubud_drinklist-digital.pdf', 'Official Ely''s Kitchen Ubud menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'ba7ea87c137384dbf5efadf47258a2e2de75ddb4866b7c221ad6cfa88cf3c6b6', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Signature Cocktails', 0), ('Wine', 1), ('Healthy Juices', 2), ('Shakes & Smoothies', 3), ('Iced Tea', 4), ('Tea', 5), ('Cognac', 6), ('Whisky', 7), ('Gin', 8), ('Rum', 9)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
