join (values ('Vegetarian All-day Breakfast', 'Potato Rösti Stack', 'Two potato rosti and 2 poached eggs, that are drizzled in vegan hollandaise sauce, served on a bed of sauted spinach, topped with layers of smoked vegan bacon.', 95000, 'IDR', 0), ('Vegetarian All-day Breakfast', 'Grecian Omelet', 'Grecian goodness: olives, feta, bell peppers, tomato, onion & spinach, encased in a delicate 3 egg omelet.', 85000, 'IDR', 1), ('Vegetarian All-day Breakfast', 'Pumpkin Omelet', 'Rolled omelet filled with soft roasted pumpkin, spinach, and vegan hollandaise, encased in a delicate 3 egg omelet.', 85000, 'IDR', 2), ('Vegetarian All-day Breakfast', 'Mediterranean Omelet', 'Artichoke, capers, olives, feta, tomato, spinach & bell peppers, encased in a delicate 3 egg omelet.', 85000, 'IDR', 3), ('Vegetarian All-day Breakfast', 'Roasted Pumpkin Omelet', 'Rolled omelet filled with soft roasted pumpkin, tomato, spinach & vegan hollandaise, encased in a delicate 3 egg omelet.', 85000, 'IDR', 4), ('Vegetarian All-day Breakfast', 'Spinach Avocado Egg', 'Gluten-free toast topped with avocado & spinach, poached eggs, roasted tomato, vegan hollandaise sauce & garnished with dukkah & seasonal greens.', 95000, 'IDR', 5), ('Vegetarian All-day Breakfast', 'Any Style Eggs', 'Your choice of eggs scrambled, poached, boiled or fried. Choice of gluten-free toast, hash brown or quinoa patty.', 65000, 'IDR', 6), ('Vegetarian All-day Breakfast', 'Paradise Pancakes', 'Almond-meal pancakes with tropical fruit salad. Choice of honey, dark chocolate sauce, or fresh coconut cream.', 95000, 'IDR', 7), ('Vegan All-day Breakfast', 'Seasonal Fruit Salad', 'Banana, dragon fruit, papaya, pineapple, strawberries, passion fruit & mango. Served with a side of vegan yogurt & chia seeds infused with coconut cream.', 60000, 'IDR', 0), ('Vegan All-day Breakfast', 'Avocado Toast', 'Sliced avocado on gluten-free toast, garnished with dukkah & seasonal greens.', 70000, 'IDR', 1), ('Vegan All-day Breakfast', 'Avocado Mushroom Ecrase', 'Guacamole, mushrooms & tomato salsa salad. Choice of gluten-free toast, hash brown, or quinoa patty.', 80000, 'IDR', 2), ('Vegan All-day Breakfast', 'Spinach Avocado Toast', 'Gluten-free bread, topped with avocado & sautéed spinach, roasted tomato, vegan hollandaise sauce, garnished with dukkah & seasonal greens.', 80000, 'IDR', 3), ('Vegan All-day Breakfast', 'Vegan Mediterranean Omelet', 'Vegan herbed feta, artichoke, capers, olives, tomato, spinach & bell peppers. Rolled in a light & fluffy chickpea omelet.', 85000, 'IDR', 4), ('Vegan All-day Breakfast', 'Vegan Grecian Omelet', 'Grecian goodness: olives, bell peppers, tomato, spinach & onion. Rolled in a light & fluffy chickpea omelet.', 85000, 'IDR', 5), ('Vegan All-day Breakfast', 'Vegan Pumpkin Omelet', 'Roasted pumpkin, spinach & scrambled tofu. Rolled in a light & fluffy chickpea omelet.', 85000, 'IDR', 6), ('Vegan All-day Breakfast', 'Vegan Mushroom Omelet', 'A scrumptious filling of scrambled tofu, sautéed mushrooms, spinach & grilled eggplant. Rolled in a light & fluffy chickpea omelet.', 85000, 'IDR', 7), ('Sandwiches (Gluten-free)', 'Vegan Club Sandwich', 'Grilled tempe and tofu, lettuce, tomato, avocado, onion. Served with a side of vegan coconut bacon and crispy potato wedges or crispy french fries, and vegan mayo. +1 dip of your choice.', 105000, 'IDR', 0), ('Sandwiches (Gluten-free)', 'Falafel Club Sandwich', 'Beetroot hummus, vegan mayonnaise, crispy lettuce, tomato, avocado, onion. Served with a side of vegan coconut bacon and crispy potato wedges or crispy french fries, and vegan mayo. +1 dip of your choice.', 105000, 'IDR', 1), ('Sandwiches (Gluten-free)', 'B.L.A.T Toasted Sandwich', 'Crispy lettuce, avocado, tomato, vegan mayonnaise, vegan coconut bacon. Served with crispy potato wedges or crispy french fries, and vegan mayo. +1 dip of your choice.', 105000, 'IDR', 2), ('Gourmet Toasties (Gluten-free)', 'Organic Chicken & Cheese Toastie', 'Grilled organic chicken, marinated in our homemade pesto, with avocado, semi-dried tomato, and cheddar cheese.', 145000, 'IDR', 0), ('Gourmet Toasties (Gluten-free)', 'Vegan Toastie', 'Grilled tempeh and tofu, marinated in our homemade pesto, with avocado, semi-dried tomato, and plant-based vegan feta.', 105000, 'IDR', 1), ('Vegan Main Course', 'Morocco Bowl', 'Quinoa, with chickpeas, roasted pumpkin, fattoush salad with cucumber, bell peppers & onion & dates. Served with vegan yogurt dressing & mango chutney.', 130000, 'IDR', 0), ('Vegan Main Course', 'Flourish Bowl', 'Falafel with broccoli, roasted pumpkin, avocado & apple on a crisp romaine lettuce, all sprinkled with sliced almonds. Served with vegan tzatziki dip, & beetroot hummus.', 120000, 'IDR', 1), ('Vegan Main Course', 'Buddha Bowl', 'Encrusted sesame seed seared tofu, edamame, wakame salad, avocado, ginger pickle, daikon radish, cherry tomatoes & carrot with Japanese dressing.', 100000, 'IDR', 2)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where slug = 'four-seasons-resort-bali-at-sayan-fitness' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Four Seasons Resort Bali at Sayan Fitness menu', 1, 'draft', 'partial', 'https://www.fourseasons.com/sayan/spa/yoga', 'Official Four Seasons Resort Bali at Sayan Fitness menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'ad7b240602e2b1209779c5a73047a6e886ec7315d257b07aaca6d43a648f27a9', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Yoga Classes', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Yoga Classes', 'Yin Yoga', 'Designed to increase elasticity and mobility of connective tissues, Yin Yoga is a slow, gentle practice suitable for all levels as a complement to more dynamic asana-based ‘yang’ practices that emphasize lengthening and contracting of muscles. In Yin Yoga, seated and supine poses are held for long durations, usually between two to five minutes each, to penetrate through muscles and reach the ligam', 400000, 'IDR', 0), ('Yoga Classes', 'Chakra Yoga', 'Each of our seven Chakra Yoga classes targets one of the key energy centres located along the spine to restore balance and harmony from the inside out.', 400000, 'IDR', 1), ('Yoga Classes', 'AntiGravity Yoga', 'This dynamic “flying” practice combines athletic strength with the motion of dance in a session that lengthens the spine and improves flexibility. Bespoke Harrison AntiGravity hammocks have been designed to safely support bodies of all ages and abilities in enhanced and inverted postures not possible in other forms of yoga to maximize the benefits even from a single session.', 160000, 'IDR', 2), ('Yoga Classes', 'Full Moon Yoga', 'Bathe in moonlight and harness the uplifting force of the universe. Balance the masculine energy of the sun with lunar vibe under the starry skies.', 400000, 'IDR', 3), ('Yoga Classes', 'Restorative Hot Stone Yoga', 'Hot stones from the Ayung River are placed on the body as static, fully supported poses are held to further penetrate the muscles and melt away layers of tension. The mind is invited to focus on breathing, invoking a deep meditative state that strengthens immune, digestive and reproductive systems. This practice is available with sound therapy upon request, using pure quartz crystal singing bowls.', 110000, 'IDR', 4), ('Yoga Classes', 'Power Yoga', 'A strong physical exercise starts by warming up the body with breathing exercises to a dynamic sun salutation combined with flow movement of yoga to increase metabolism, burn calories and contour the body.', 400000, 'IDR', 5), ('Yoga Classes', 'Laughter Yoga', 'This unique exercise routine combines the freedom and health benefits of laughter with yogic breathing (pranayama) and asanas (poses): a simple and playful way to flood the body with oxygen and promote a natural sense of joy.', 400000, 'IDR', 6), ('Yoga Classes', 'Hatha Yoga', 'This session begins with focused breathing exercises, followed by a warm up with the Surya Namaskara (sunrise or sunset salutation). It continues with yoga positions that support the body’s core strength and ends with relaxation poses. Complimentary for in-house guests (subject to change and fee applies when a visiting yoga practitioner is in residence).', 400000, 'IDR', 7), ('Yoga Classes', 'Easy Yoga', 'Introduce yourself to the fundamentals of yoga through slow and soft postures and deep opening stretches that restore and reground. This practice is for beginners or those who seek a gentler class. Complimentary for in-house guests (subject to change and fee applies when a visiting yoga practitioner is in residence).', 400000, 'IDR', 8)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

