with target as (
  select slug from venues where slug = 'heart-space-bali' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Heart Space Bali menu', 1, 'draft', 'partial', 'https://www.heartspacebali.com/service-page/healing-yin-yoga', 'Official Heart Space Bali menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '7979d1fb965eb5490a8c4f9a822bea5dac57cab82df8e8a4ae27d96bd45955ed', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Healing Yin Yoga', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Healing Yin Yoga', 'Healing Yin Yoga', 'Release tension, calm your mind & nurture deep healing through Yin Yoga.', 165000, 'IDR', 0), ('Healing Yin Yoga', 'Class Only - Regular price', 'Regular price for the class.', 165000, 'IDR', 1), ('Healing Yin Yoga', 'Class Only - KITAS/KITAP holders', 'Discounted price for KITAS/KITAP holders.', 110000, 'IDR', 2), ('Healing Yin Yoga', 'Class Only - Indonesian citizens', 'Discounted price for Indonesian citizens.', 110000, 'IDR', 3), ('Healing Yin Yoga', 'Class Only - Balinese locals', 'Pay what you can as donation for Balinese locals.', null, null, 4), ('Healing Yin Yoga', 'Class + Juice', 'Enjoy a refreshing cold-pressed juice at Flourish.', 45000, 'IDR', 5), ('Healing Yin Yoga', '5 Session Package', 'Package of five classes.', 700000, 'IDR', 6)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

