join (values ('Breads & Dips', 'TURKISH FLAT BREAD', 'cooked over fire coals / finished with za''atar salt', 55000, 'IDR', 0), ('Breads & Dips', 'GRILLED SOURDOUGH BREAD', 'rosemary / parmesan / house smoked lardo', 85000, 'IDR', 1), ('Breads & Dips', 'WHIPPED CHICKPEA HUMMUS', 'falafel / green olive / parsley', 95000, 'IDR', 2), ('Breads & Dips', 'SPINACH BORANI', 'Turkish flat bread / house olive', 175000, 'IDR', 3), ('Breads & Dips', 'MEZZE PLATE', 'homemade pickles / dolma / cucumber tzatziki / green olive hummus / harissa babaganoush / puffed Lebanese bread', 185000, 'IDR', 4)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

