  select t.slug, 'Massage & Treatments', 1, 'draft', 'partial', 'https://karsaspa.com/our-massages', 'Official Karsa Spa menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'ccc954b2806cbe89cfe78497d3dc3cd596a85226141b8de920a63f0eef64036e', 'spa'
