with target as (
  select slug from venues where slug = 'moonstone-beach-lounge' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Moonstone Beach Lounge menu', 1, 'draft', 'partial', 'https://moonstonebeachlounge.com/wp-content/uploads/2025/12/MSBL-FOOD-MENU-2026.pdf', 'Official Moonstone Beach Lounge menu',
