  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Signature dish', 0), ('Bar Bites Menu', 1), ('Salads', 2), ('Starter', 3), ('Soup & Bowl', 4), ('Signature dish (2)', 5), ('Mains', 6), ('Megibung', 7), ('Pizza & Pasta', 8), ('Signature sweet', 9), ('Sandwich and Burger', 10), ('Kids selections', 11), ('Dessert selections', 12)) as s(name, pos)
