with target as (
  select slug from venues where slug = 'semara-grill-at-inara-alas-harum' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'SE·MA·RA', 1, 'draft', 'partial', 'https://inarahotels.com/alas-harum-resort-bali/wp-content/uploads/2025/08/Beverage-Semara.pdf', 'Official Semara Grill at Inara Alas Harum menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '989dc967132eae3c5cd4978ed2a5beced661e96d1b348d3d5f670fb525cbba9a', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('LIMONCELLO LOVERS', 0), ('SE•MA•RA SIGNATURE', 1)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('LIMONCELLO LOVERS', 'MOJITO', 'Limoncello, mint leaves, lime, sugar, club soda.', 120000, 'IDR', 0), ('LIMONCELLO LOVERS', 'LEMONADE', 'Homemade limoncello liqueur, orange liqueur, lemon, sprite.', 120000, 'IDR', 1), ('LIMONCELLO LOVERS', 'MULE', 'Limoncello, lemon juice, honey, homemade ginger beer.', 120000, 'IDR', 2), ('LIMONCELLO LOVERS', 'SANGRIA SELECTION', null, null, null, 3), ('LIMONCELLO LOVERS', 'GLASS', null, null, null, 4), ('LIMONCELLO LOVERS', 'ROJA', 'Red wine, orange liqueur, oleo saccharum, sweet spices, soda.', 120000, 'IDR', 5), ('LIMONCELLO LOVERS', 'PITCHER', null, null, null, 6), ('LIMONCELLO LOVERS', 'BLANCO', 'White wine, rum, tepache, apple, lemon, sprite.', 120000, 'IDR', 7), ('LIMONCELLO LOVERS', 'ROSADO', 'Rosé wine, umeshu plum, strawberry, peach, spiced honey syrup.', 120000, 'IDR', 8), ('SE•MA•RA SIGNATURE', 'THE PROLOGUE', 'The story begins when the heavenly realms are attacked by the Great Giant Nilarudraka, who seeks to conquer the heavens. A great battle ensues between the gods and the giants, and the outcome cannot be undone. After a long battle, the gods are ultimately defeated by the Great Giant Nilarudraka.', 155000, 'IDR', 0), ('SE•MA•RA SIGNATURE', 'THE PROPHECY', 'After the defeat, the god sought Bhagawan Wrespati to foresee the one who could defeat the giant. The prophecy revealed that the one destined to vanquish the giant was the son of Lord Shiva, who had an elephant head.', 155000, 'IDR', 1), ('SE•MA•RA SIGNATURE', 'THE INTRUDER', 'It turns out that Lord Shiva is still meditating on Mount Kailasa, and no god or mortal dares to interrupt him. So, the gods send Lord Semara to provoke Lord Shiva. Lord Semara shoots Lord Shiva with the "Panah Asmara" (Arrow of Love), and the arrow strikes Lord Shiva''s chest. Angered, Lord Shiva awakens, kills Lord Semara, and turns him into ashes, unaware of the truth.', 155000, 'IDR', 2), ('SE•MA•RA SIGNATURE', 'THE SACRIFICE', 'The death of Lord Semara causes his wife, Lady Ratih, to mourn in sorrow. As a sign of her love and loyalty, Lady Ratih begs Lord Shiva to burn her as well, so she can share the same fate as her husband. Lord Shiva grants her wish.', 145000, 'IDR', 3), ('SE•MA•RA SIGNATURE', 'THE TRUTH', 'As the arrow shot was the "Panah Asmara," Lord Shiva couldn''t help but feel a longing for his wife, Lady Uma. They finally reunited to share their love. A few days later, while walking on Mount Kailasa, Lady Uma noticed a pile of ashes. She asked Lord Shiva about it, and after Lord Shiva explained, Lady Uma begged him to bring Lord Semara and Lady Ratih back to life.', 135000, 'IDR', 4), ('SE•MA•RA SIGNATURE', 'THE FAITH', 'Finally, Lord Shiva granted his wife''s wish on one condition: Lord Semara and Lady Ratih could not live in the heavenly realms. Instead, Lord Shiva spread their ashes into the "Mayapada Realms" (Mortal Realms), with the intention that all living souls would feel the sense of love within their souls, "Purusa & Predana."', 125000, 'IDR', 5)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

