ith Paratha Bread.', 85000, 'IDR', 3), ('Vegetarian Delight', 'Fried Rice', 'Traditional Indonesian Fried Rice served with Vegetables and Fried Tofu.', 85000, 'IDR', 4), ('Vegetarian Delight', 'Chickpea Curry', 'A Flavourful Curry with Chickpeas, Cherry Tomatoes, and Spices.', 78000, 'IDR', 5), ('Vegetarian Delight', 'Rice Noodles', 'Stir-Fried Rice Noodles served with Vegetables and Soy Bean.', 85000, 'IDR', 6), ('Vegetarian Delight', 'Samosa', 'Vegetable Samosa served with Green Salad Vinaigrette and Red Chili Sauce.', 75000, 'IDR', 7)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where slug = '360-move-uluwatu' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Membership & Pricing', 1, 'draft', 'partial', 'https://360moveuluwatu.com/schedule-and-membership', 'Official 360 Move Uluwatu menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '4fd4df74765d895f2a76ac5d7797c59b6f57b5b72c18a8c01f2ae9daf7843932', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('360 Move Classes', 0), ('360 Move Open Gym', 1), ('Personal Sessions', 2)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('360 Move Classes', 'Drop-in', 'Access to classes without prior booking.', 150000, 'IDR', 0), ('360 Move Classes', 'Day Pass', 'Full day access to all classes.', 200000, 'IDR', 1), ('360 Move Classes', '5 Class Pass', 'Access to any 5 classes.', 650000, 'IDR', 2), ('360 Move Open Gym', 'Drop-in', 'Access to gym facilities for one session.', 100000, 'IDR', 0), ('360 Move Open Gym', '7 Days', 'Unlimited access for 7 days.', 400000, 'IDR', 1), ('360 Move Open Gym', '14 Days', 'Unlimited access for 14 days.', 675000, 'IDR', 2), ('360 Move Open Gym', '30 Days', 'Unlimited access for 30 days.', 875000, 'IDR', 3), ('Personal Sessions', 'Physiotherapy - 5 Sessions', 'Package of five physiotherapy sessions.', 6500, 'IDR', 0), ('Personal Sessions', 'Physiotherapy - 10 Sessions', 'Package of ten physiotherapy sessions.', 12000, 'IDR', 1)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

