with target as (
  select slug from venues where slug = 'base-restaurant-at-hideaway-villas-bali-uluwatu' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Hideaway Wellness', 1, 'draft', 'partial', 'https://hideawayvillasbali.com/uluwatu/wellness-uluwatu', 'Official Base Restaurant at Hideaway Villas Bali Uluwatu menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '773d71268b2d9b9043c08ff2db94a4c09f4bed8bd33ec99da108309feef2e509', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Massage', 0), ('BODY SCRUBS & WRAPS', 1)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Massage', 'TRADITIONAL', 'This full-body oil massage is a journey through Southeast Asia, using relaxing and restorative techniques. Dry acupressure to begin, firm longitudinal strokes, deep tissue, and mobilization techniques will relieve tired limbs and musculoskeletal discomfort. Medium to strong pressure.', 300000, 'IDR', 0), ('Massage', 'SLUMBER', 'Imagine the gentle breeze through the trees and the sound of the ocean, surrender to serenity, with this deeply relaxing, and calming full-body oil massage. Flowing soft to medium pressure is used via effleurage, petrissage, and bioenergetic techniques. An excellent antidote to jetlag, hypertension, anxiety, and insomnia.', 300000, 'IDR', 1), ('Massage', 'QUICK FIX', 'For those not wishing to have an oil massage, this treatment is a dry full-body treatment, incorporating breathwork, acupressure, shiatsu, stretching, and mobilization techniques. Recommended for yogis, surfers, golfers, gym-goers, active people seeking a dynamic, interactive approach.', 300000, 'IDR', 2), ('Massage', 'HOT ROCK', 'Imagine the gentle breeze through the trees and the sound of the ocean, surrender to serenity, with this deeply relaxing, and calming full-body oil massage. Flowing soft to medium pressure is used via effleurage, petrissage, and bioenergetic techniques. An excellent antidote to jetlag, hypertension, anxiety, and insomnia.', 650000, 'IDR', 3), ('Massage', 'BACK, NECK, SHOULDERS', 'A back, neck and shoulder massage using warmed herbal oil designed to address specific discomfort, neck, shoulder, tendon adhesions, and pain.', 225000, 'IDR', 4), ('Massage', 'SCALP MASSAGE', 'Clear any congestion and tension with this firm and awakening scalp massage. Great for headaches, a ''busy head,'' and daily stresses and strains.', 225000, 'IDR', 5), ('Massage', 'FOOT THERAPY', 'This treatment begins with a warm foot ritual in a floral foot bath. Followed with an invigorating salt scrub, and warmed oil massage to the lower legs and feet, completed with warmed aromatic towels. For foot weary travelers this treatment effectively relieves stress, improves blood circulation, stimulate sensory never endings, hydrates the skin, and promotes relaxation.', 300000, 'IDR', 6), ('Massage', 'FOOT THERAPY (90 mins)', 'This treatment begins with a warm foot ritual in a floral foot bath. Followed with an invigorating salt scrub, and warmed oil massage to the lower legs and feet, completed with warmed aromatic towels. For foot weary travelers this treatment effectively relieves stress, improves blood circulation, stimulate sensory never endings, hydrates the skin, and promotes relaxation.', 450000, 'IDR', 7), ('BODY SCRUBS & WRAPS', 'SALT AND OIL SCRUB', 'An invigorating full body aromatherapeutic oil and salt exfoliation with hot aromatic towels, will leave your skin glowing, deeply hydrated and refreshed.', 350000, 'IDR', 0), ('BODY SCRUBS & WRAPS', 'INDONESIAN LULUR', 'A full-body scrub made with indigenous herbs and spices, to warm, purify, and cleanse the body. Floral scented hot towels, create calm and clarity, whilst sloughing away dry, dead skin cells.', 350000, 'IDR', 1), ('BODY SCRUBS & WRAPS', 'SUN RECOVERY', 'This treatment is specifically for sunburn, gentle and cooling, enjoy a healing aloe vera full-body wrap with a relaxing scalp massage before a light body cleanse and hydrating lotion is applied…leave sun-kissed and soothed.', 350000, 'IDR', 2), ('BODY SCRUBS & WRAPS', 'EXPRESS FACIAL REFRESHER', 'This facial refresh starts with cleansing and toning, before the skin is exfoliated, hydrating lotion with facial massage and lastly serum is applied. Great for dull tired complexions in need of a quick fix.', 400000, 'IDR', 3), ('BODY SCRUBS & WRAPS', 'FACE MASSAGE', 'A quick cleanse prior to a lifting and firming massage that includes the use of a jade gua sha. The botanical oil deeply hydrates dry and dehydrated skin, whilst the massage firms and refreshed with the final use of iced jade rollers.', 400000, 'IDR', 4)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

