with target as (
  select slug from venues where slug = 'daily-social' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Our Menu', 1, 'draft', 'partial', 'https://www.dailysocialbali.com/our-menus', 'Official Daily Social menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'c0f76f59668cdd03d2e9ee1dea641d42c725d45c0072e70f716a19a21a7b4178', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('All-Day Dining', 0), ('Soup', 1), ('Main Western', 2), ('Asian Comfort', 3), ('Local Flare', 4), ('Plant Based', 5), ('Kids', 6), ('Lunch & Dinner', 7)) as s(name, pos)
  returning id, name
)
