with target as (
  select slug from venues where slug = 'warnakali-restaurant-at-adiwana-warnakali-resort' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Warnakali Restaurant at Adiwana Warnakali Resort menu', 1, 'draft', 'partial', 'https://warnakalirestaurant.com/menu', 'Official Warnakali Restaurant at Adiwana Warnakali Resort menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '5d014f50565339bcca9dcf25798305b9392b37c0d9a6c1f4f5bdc097732da05f', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('APPETIZER', 0), ('SOUP', 1), ('MAIN COURSE', 2), ('CHEF RECOMMENDATION', 3), ('BURGER & SANDWICH', 4), ('DESSERT', 5), ('PIZZA & PASTA', 6), ('BEVERAGE', 7)) as s(name, pos)
  returning id, name
)
